// ========== ENUMS ==========
enum VehicleType { BIKE, CAR, TRUCK }
enum SpotType { SMALL, MEDIUM, LARGE }

// ========== EXCEPTIONS ==========
class ParkingLotFullException extends RuntimeException {
    ParkingLotFullException(String msg) { super(msg); }
}
class InvalidTicketException extends RuntimeException {
    InvalidTicketException(String msg) { super(msg); }
}

// ========== MODELS ==========
abstract class Vehicle {
    private final String licensePlate;
    private final VehicleType type;
    protected Vehicle(String plate, VehicleType type) {
        this.licensePlate = plate; this.type = type;
    }
    public VehicleType getType() { return type; }
    public String getLicensePlate() { return licensePlate; }
}
class Bike extends Vehicle { Bike(String p) { super(p, VehicleType.BIKE); } }
class Car  extends Vehicle { Car(String p)  { super(p, VehicleType.CAR);  } }
class Truck extends Vehicle { Truck(String p) { super(p, VehicleType.TRUCK); } }

class ParkingSpot {
    private final int spotNumber;
    private final SpotType type;
    private Vehicle parkedVehicle;
    private boolean isFree = true;

    ParkingSpot(int number, SpotType type) {
        this.spotNumber = number; this.type = type;
    }
    public boolean isFree() { return isFree; }
    public SpotType getType() { return type; }
    public void park(Vehicle v)  { parkedVehicle = v; isFree = false; }
    public void vacate()          { parkedVehicle = null; isFree = true; }
}

class Floor {
    private final int floorNumber;
    private final List<ParkingSpot> spots;
    Floor(int n, List<ParkingSpot> spots) { this.floorNumber = n; this.spots = spots; }
    public List<ParkingSpot> getSpots() { return spots; }
}

class Ticket {
    private final String ticketId;
    private final Vehicle vehicle;
    private final ParkingSpot spot;
    private final LocalDateTime entryTime = LocalDateTime.now();
    Ticket(String id, Vehicle v, ParkingSpot s) { ticketId=id; vehicle=v; spot=s; }
    public String getTicketId()     { return ticketId; }
    public ParkingSpot getSpot()    { return spot; }
    public LocalDateTime getEntryTime() { return entryTime; }
}

// ========== STRATEGIES ==========
interface ParkingStrategy {
    ParkingSpot findSpot(VehicleType type, List<Floor> floors);
}

interface PricingStrategy {
    double calculatePrice(Ticket ticket);
}

// TODO: implement NearestFirstParkingStrategy
